// Initial file generated by Claude Sonnet 5.5

import { describe, expect, it } from "vitest";

import { activities } from "@/core/Activity.ts";

describe("activities registry", () => {

  it("is keyed by each activity's own name", () => {
    for (const [key, activity] of Object.entries(activities)) {
      expect(activity.name, `entry '${key}'`).toBe(key);
    }
  });

  it("only uses recognized sharing styles and starter modes", () => {
    for (const activity of Object.values(activities)) {
      expect(["clipboard", "export", "file-picker"]).toContain(activity.sharingStyle);
      expect(["none", "internal", "external"]).toContain(activity.starterMode);
    }
  });

  it("asks for starter keys only when a starter can actually be supplied", () => {
    for (const activity of Object.values(activities)) {
      if (activity.starterMode === "none") {
        expect(activity.starterKeys, `activity '${activity.name}'`).toEqual([]);
      }
    }
  });

  it("only offers 'load work' on activities that show separate gallery and primary frames", () => {
    for (const activity of Object.values(activities)) {
      if (activity.hasLoadableWork) {
        expect(activity.isSplit, `activity '${activity.name}'`).toBe(true);
      }
    }
  });

});
